// Kanji index for handwriting practice (generated by `npm run kanji`). Stroke paths and usage
// examples are fetched per kanji from /kanji/<id>.json so they stay out of the page bundle and the Worker.
import {z} from 'zod';
import data from './generated/kanji.json';
import {localizedText} from './schemas';

export type KanjiInfo = {
  id: string; char: string; level: string; on: string[]; kun: string[];
  meanings: {en: string; ru: string}; strokes: number;
};

export const kanjiList = data as KanjiInfo[];
const byId = new Map(kanjiList.map(kanji => [kanji.id, kanji]));

export function getKanji(id: string): KanjiInfo | undefined {return byId.get(id);}

const detailSchema = z.object({
  strokes: z.array(z.string().min(1)).min(1),
  words: z.array(z.object({japanese: z.string().min(1), reading: z.string().min(1), meanings: localizedText})).default([]),
  sentences: z.array(z.object({japanese: z.string().min(1), ruby: z.string().optional(), translations: localizedText})).default([])
});
export type KanjiDetail = z.infer<typeof detailSchema>;

const detailCache = new Map<string, Promise<KanjiDetail>>();
export function loadKanjiDetail(id: string): Promise<KanjiDetail> {
  let pending = detailCache.get(id);
  if (!pending) {
    pending = fetch(`/kanji/${id}.json`).then(async response => {
      if (!response.ok) throw new Error(`Kanji data ${id}: ${response.status}`);
      const parsed = detailSchema.safeParse(await response.json());
      if (!parsed.success) throw new Error(`Kanji data ${id}: bad format`);
      return parsed.data;
    });
    pending.catch(() => detailCache.delete(id));
    detailCache.set(id, pending);
  }
  return pending;
}
